/**
 * Platform binding for registration identifiers.
 *
 * L4. The only place `confirmation_reference` is produced for real use.
 *
 * `registration_id` is NOT generated here. It is generated by PostgreSQL: `gen_random_uuid()` has
 * been a core function since PostgreSQL 13, so no extension is required, and the column DEFAULT
 * means a caller cannot supply a colliding or reused value. See `0001_initial.sql`.
 *
 * `confirmation_reference` is generated here, because the student-facing format is a presentation
 * concern and belongs above the database. Its uniqueness is still enforced by a UNIQUE constraint in
 * the schema; this function only makes collisions improbable.
 *
 * Binding entropy to `node:crypto` lives here rather than in src/domain because reading entropy is
 * I/O and L3 must not perform it (SYSTEM-ARCHITECTURE.md section 2.1).
 */

import { randomBytes } from "node:crypto";

import { entropyFromBytes, generateConfirmationReference } from "../domain/registration-reference.js";

/**
 * Draw a single byte from the system CSPRNG.
 *
 * `randomBytes(1)` returns a one-element array. The fallback keeps the type non-nullable; it is
 * unreachable in practice, because `randomBytes(1)` either yields a length-1 buffer or throws.
 */
function issueRandomByte(): number {
  return randomBytes(1)[0] ?? 0;
}

/** A confirmation reference drawn from the system CSPRNG. */
export function newConfirmationReference(): string {
  return generateConfirmationReference(entropyFromBytes(issueRandomByte));
}